fn int_to_str(n: Int) -> Str {
    let chars = vec()
    let mut num = n
    while num > 0 {
        chars.push(int_to_char(num % 10))
        num = num / 10
    }
    let mut result = ""
    for c in chars {
        result = result + c
    }
    result
}

